const { useState } = React;

function App() {
  const [page, setPage] = useState("settings");
  const [pushNotifications, setPushNotifications] = useState(true);
  const [emailUpdates, setEmailUpdates] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  if (page === "login") {
    return (
      <main style={styles.loginContainer}>
        <h1 style={styles.loginHeading}>Login Page</h1>
        <button
          style={styles.loginButton}
          onClick={() => setPage("settings")}
          aria-label="Go to Settings"
        >
          Go to Settings
        </button>
      </main>
    );
  }

  return (
    <main style={styles.container}>
      <h1 style={styles.heading}>Settings</h1>

      <section aria-labelledby="notifications-label" style={styles.section}>
        <h2 id="notifications-label" style={styles.subheading}>
          Notifications
        </h2>

        <label style={styles.toggleLabel}>
          <input
            type="checkbox"
            checked={pushNotifications}
            onChange={() => setPushNotifications(!pushNotifications)}
            style={styles.toggleInput}
            aria-checked={pushNotifications}
          />
          <span style={styles.toggleSwitch} aria-hidden="true"></span>
          Push notifications
        </label>

        <label style={styles.toggleLabel}>
          <input
            type="checkbox"
            checked={emailUpdates}
            onChange={() => setEmailUpdates(!emailUpdates)}
            style={styles.toggleInput}
            aria-checked={emailUpdates}
          />
          <span style={styles.toggleSwitch} aria-hidden="true"></span>
          Email updates
        </label>

        <label style={styles.toggleLabel}>
          <input
            type="checkbox"
            checked={darkMode}
            onChange={() => setDarkMode(!darkMode)}
            style={styles.toggleInput}
            aria-checked={darkMode}
          />
          <span style={styles.toggleSwitch} aria-hidden="true"></span>
          Dark mode
        </label>
      </section>

      <hr style={styles.divider} />

      <button
        style={styles.logoutButton}
        onClick={() => setPage("login")}
        aria-label="Log out and return to login page"
      >
        Log out
      </button>

      <nav style={styles.nav} aria-label="Settings navigation">
        <a href="#" style={styles.privacyLink} onClick={e => e.preventDefault()}>
          Privacy policy
        </a>
      </nav>

      <style>{`
        input[type=checkbox] {
          position: absolute;
          opacity: 0;
          width: 0;
          height: 0;
        }

        input[type=checkbox] + span {
          position: relative;
          display: inline-block;
          width: 36px;
          height: 20px;
          background: #ccc;
          border-radius: 12px;
          vertical-align: middle;
          margin-right: 10px;
          transition: background-color 0.3s;
        }

        input[type=checkbox] + span::before {
          content: "";
          position: absolute;
          left: 2px;
          top: 2px;
          width: 16px;
          height: 16px;
          background: white;
          border-radius: 50%;
          transition: transform 0.3s;
          box-shadow: 0 0 2px rgba(0,0,0,0.2);
        }

        input[type=checkbox]:checked + span {
          background: #4caf50;
        }

        input[type=checkbox]:checked + span::before {
          transform: translateX(16px);
        }
      `}</style>
    </main>
  );
}

const styles = {
  container: {
    maxWidth: 360,
    margin: "20px auto",
